            <Tel>col:$journal.pat_personal_main.pat_contact_info.tel1</Tel>
            <Comment>col:$journal.detail.pat_main_3.pat_memo_info.content</Comment>
        </PatientEtcInfo>
        <PatientDIALYSISInfo>
