            <GENSIKKAN Code="col:$journal.detail.pat_unique.medical_hst_info.disease_cd">col:$journal.detail.pat_unique.medical_hst_info.disease_name</GENSIKKAN>
            <GENSIKKANYMD>col:$journal.detail.pat_unique.medical_hst_info.disease_date</GENSIKKANYMD>
            <TENKI>col:$journal.detail.pat_unique.medical_hst_info.out_come</TENKI>
            <TENKIYMD>col:$journal.detail.pat_unique.medical_hst_info.out_come_date</TENKIYMD>
            <DIEDOF Code="col:$journal.pat_personal_main.die_cd">col:$journal.pat_personal_main.die_name</DIEDOF>
            <DOUNYU></DOUNYU><!-- 導入院所; 連携対象外 -->
            <SYOKAI></SYOKAI><!-- 紹介院所; 連携対象外 -->
            <Ctr>col:$journal.detail.pat_unique_1.physical_info.ctr</Ctr>
            <CTR_UPDATE>col:$journal.detail.pat_unique_1.physical_info.exam_date</CTR_UPDATE>
            <Doctor detail="患者主治医,Code"></Doctor>
            <DialysisDoctor detail="透析主治医,Code"></DialysisDoctor>
            <DialysisNurse detail="透析看護師,Code"></DialysisNurse>
        </PatientDIALYSISInfo>
        <AdmissionInfo>
            <!-- 入院情報 -->
            <AdmissionStatus>col:$journal.pat_personal_main.in_out_class</AdmissionStatus>
            <Ward Code="col:$journal.pat_main.medical_care_info.ward_cd"></Ward>
            <InRoom Code=""></InRoom><!-- 連携対象外 -->
            <Bed Code=""></Bed><!-- 連携対象外 -->
            <AdmissionDate></AdmissionDate><!-- 連携対象外 -->
            <DischargeDate></DischargeDate><!-- 連携対象外 -->
            <AdmissionSnk Code="col:$journal.pat_main.medical_care_info.main_course_cd"></AdmissionSnk>
            <AdmissionDoctor detail="入院主治医,Code"></AdmissionDoctor>
        </AdmissionInfo>
        <InsuranceInfo ctlNo="col:$journal.detail.pat_insurance.ctl_no,const:0">
            <!-- 主保険情報 -->
            <InsuranceNumber>col:$journal.detail.pat_insurance.insu_info.insu_no</InsuranceNumber>
            <InsuranceDivision>col:$journal.detail.pat_insurance.insu_info.insu_kbn</InsuranceDivision>
            <InsuredSign>col:$journal.detail.pat_insurance.insu_info.insu_pat_mark</InsuredSign>
            <InsuredNumber>col:$journal.detail.pat_insurance.insu_info.insu_pat_no</InsuredNumber>
        </InsuranceInfo>
        <InfectionInfo>
            <!-- 感染症情報 -->
            <Infection detail="感染症情報,Code"></Infection>
        </InfectionInfo>
        <AllergyInfo>
            <!-- アレルギー情報 -->
            <Allergy detail="アレルギー情報,Code"></Allergy>
        </AllergyInfo>
        <DrugAllergyInfo>
            <!-- 薬剤アレルギー情報 -->
            <Drug detail="薬剤アレルギー情報,Code"></Drug>
        </DrugAllergyInfo>
    </PatientData>
